use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::Path;

mod elf_parser;
mod html_generator;

use elf_parser::{ElfFile, parse_elf};
use html_generator::generate_html;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        eprintln!("Usage: elfcat <filename>");
        eprintln!("Writes <filename>.html to CWD.");
        std::process::exit(1);
    }

    let input_path = &args[1];
    let output_path = format!("{}.html", input_path);

    // Read the file
    let mut file = match fs::File::open(input_path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Failed to read file \"{}\": {}", input_path, e);
            std::process::exit(1);
        }
    };

    let mut data = Vec::new();
    if let Err(e) = file.read_to_end(&mut data) {
        eprintln!("Failed to read file \"{}\": {}", input_path, e);
        std::process::exit(1);
    }

    // Parse the ELF file
    let elf_file = match parse_elf(&data, input_path) {
        Ok(elf) => elf,
        Err(e) => {
            eprintln!("Error parsing ELF: {}", e);
            std::process::exit(1);
        }
    };

    // Generate HTML
    let html = generate_html(&elf_file, &data);

    // Write output
    if let Err(e) = fs::write(&output_path, html) {
        eprintln!("Failed to write output file \"{}\": {}", output_path, e);
        std::process::exit(1);
    }
}
