use std::fmt;

#[derive(Debug, Clone)]
pub struct ElfFile {
    pub filename: String,
    pub file_size: u64,
    pub header: ElfHeader,
    pub program_headers: Vec<ProgramHeader>,
    pub section_headers: Vec<SectionHeader>,
}

#[derive(Debug, Clone)]
pub struct ElfHeader {
    pub class: ElfClass,
    pub data: ElfData,
    pub version: u8,
    pub osabi: u8,
    pub abiversion: u8,
    pub e_type: u16,
    pub e_machine: u16,
    pub e_version: u32,
    pub e_entry: u64,
    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
}

#[derive(Debug, Clone, Copy)]
pub enum ElfClass {
    Bits32,
    Bits64,
}

#[derive(Debug, Clone, Copy)]
pub enum ElfData {
    LittleEndian,
    BigEndian,
}

#[derive(Debug, Clone)]
pub struct ProgramHeader {
    pub p_type: u32,
    pub p_flags: u32,
    pub p_offset: u64,
    pub p_vaddr: u64,
    pub p_paddr: u64,
    pub p_filesz: u64,
    pub p_memsz: u64,
    pub p_align: u64,
}

#[derive(Debug, Clone)]
pub struct SectionHeader {
    pub sh_name: u32,
    pub sh_type: u32,
    pub sh_flags: u64,
    pub sh_addr: u64,
    pub sh_offset: u64,
    pub sh_size: u64,
    pub sh_link: u32,
    pub sh_info: u32,
    pub sh_addralign: u64,
    pub sh_entsize: u64,
}

pub fn parse_elf(data: &[u8], filename: &str) -> Result<ElfFile, String> {
    if data.len() < 20 {
        return Err("File too small to be ELF".to_string());
    }

    // Check magic number
    if &data[0..4] != b"\x7fELF" {
        return Err("Invalid ELF magic number".to_string());
    }

    let class = match data[4] {
        1 => ElfClass::Bits32,
        2 => ElfClass::Bits64,
        _ => return Err("Invalid ELF class".to_string()),
    };

    let data_encoding = match data[5] {
        1 => ElfData::LittleEndian,
        2 => ElfData::BigEndian,
        _ => return Err("Invalid ELF data encoding".to_string()),
    };

    let version = data[6];
    let osabi = data[7];
    let abiversion = data[8];

    // Parse header based on class
    let header = match class {
        ElfClass::Bits32 => parse_elf32_header(data, data_encoding)?,
        ElfClass::Bits64 => parse_elf64_header(data, data_encoding)?,
    };

    // Parse program headers
    let mut program_headers = Vec::new();
    if header.e_phoff > 0 && header.e_phnum > 0 {
        for i in 0..header.e_phnum {
            let offset = header.e_phoff as usize + (i as usize * header.e_phentsize as usize);
            let ph = match class {
                ElfClass::Bits32 => parse_program_header_32(data, offset, data_encoding)?,
                ElfClass::Bits64 => parse_program_header_64(data, offset, data_encoding)?,
            };
            program_headers.push(ph);
        }
    }

    // Parse section headers
    let mut section_headers = Vec::new();
    if header.e_shoff > 0 && header.e_shnum > 0 {
        for i in 0..header.e_shnum {
            let offset = header.e_shoff as usize + (i as usize * header.e_shentsize as usize);
            let sh = match class {
                ElfClass::Bits32 => parse_section_header_32(data, offset, data_encoding)?,
                ElfClass::Bits64 => parse_section_header_64(data, offset, data_encoding)?,
            };
            section_headers.push(sh);
        }
    }

    Ok(ElfFile {
        filename: filename.to_string(),
        file_size: data.len() as u64,
        header: ElfHeader {
            class,
            data: data_encoding,
            version,
            osabi,
            abiversion,
            e_type: header.e_type,
            e_machine: header.e_machine,
            e_version: header.e_version,
            e_entry: header.e_entry,
            e_phoff: header.e_phoff,
            e_shoff: header.e_shoff,
            e_flags: header.e_flags,
            e_ehsize: header.e_ehsize,
            e_phentsize: header.e_phentsize,
            e_phnum: header.e_phnum,
            e_shentsize: header.e_shentsize,
            e_shnum: header.e_shnum,
            e_shstrndx: header.e_shstrndx,
        },
        program_headers,
        section_headers,
    })
}

struct ParsedHeader {
    e_type: u16,
    e_machine: u16,
    e_version: u32,
    e_entry: u64,
    e_phoff: u64,
    e_shoff: u64,
    e_flags: u32,
    e_ehsize: u16,
    e_phentsize: u16,
    e_phnum: u16,
    e_shentsize: u16,
    e_shnum: u16,
    e_shstrndx: u16,
}

fn parse_elf32_header(data: &[u8], endian: ElfData) -> Result<ParsedHeader, String> {
    if data.len() < 52 {
        return Err("File too small for ELF32 header".to_string());
    }

    Ok(ParsedHeader {
        e_type: read_u16(&data[16..18], endian),
        e_machine: read_u16(&data[18..20], endian),
        e_version: read_u32(&data[20..24], endian),
        e_entry: read_u32(&data[24..28], endian) as u64,
        e_phoff: read_u32(&data[28..32], endian) as u64,
        e_shoff: read_u32(&data[32..36], endian) as u64,
        e_flags: read_u32(&data[36..40], endian),
        e_ehsize: read_u16(&data[40..42], endian),
        e_phentsize: read_u16(&data[42..44], endian),
        e_phnum: read_u16(&data[44..46], endian),
        e_shentsize: read_u16(&data[46..48], endian),
        e_shnum: read_u16(&data[48..50], endian),
        e_shstrndx: read_u16(&data[50..52], endian),
    })
}

fn parse_elf64_header(data: &[u8], endian: ElfData) -> Result<ParsedHeader, String> {
    if data.len() < 64 {
        return Err("File too small for ELF64 header".to_string());
    }

    Ok(ParsedHeader {
        e_type: read_u16(&data[16..18], endian),
        e_machine: read_u16(&data[18..20], endian),
        e_version: read_u32(&data[20..24], endian),
        e_entry: read_u64(&data[24..32], endian),
        e_phoff: read_u64(&data[32..40], endian),
        e_shoff: read_u64(&data[40..48], endian),
        e_flags: read_u32(&data[48..52], endian),
        e_ehsize: read_u16(&data[52..54], endian),
        e_phentsize: read_u16(&data[54..56], endian),
        e_phnum: read_u16(&data[56..58], endian),
        e_shentsize: read_u16(&data[58..60], endian),
        e_shnum: read_u16(&data[60..62], endian),
        e_shstrndx: read_u16(&data[62..64], endian),
    })
}

fn parse_program_header_32(data: &[u8], offset: usize, endian: ElfData) -> Result<ProgramHeader, String> {
    if offset + 32 > data.len() {
        return Err("Not enough data for program header".to_string());
    }

    Ok(ProgramHeader {
        p_type: read_u32(&data[offset..offset+4], endian),
        p_offset: read_u32(&data[offset+4..offset+8], endian) as u64,
        p_vaddr: read_u32(&data[offset+8..offset+12], endian) as u64,
        p_paddr: read_u32(&data[offset+12..offset+16], endian) as u64,
        p_filesz: read_u32(&data[offset+16..offset+20], endian) as u64,
        p_memsz: read_u32(&data[offset+20..offset+24], endian) as u64,
        p_flags: read_u32(&data[offset+24..offset+28], endian),
        p_align: read_u32(&data[offset+28..offset+32], endian) as u64,
    })
}

fn parse_program_header_64(data: &[u8], offset: usize, endian: ElfData) -> Result<ProgramHeader, String> {
    if offset + 56 > data.len() {
        return Err("Not enough data for program header".to_string());
    }

    Ok(ProgramHeader {
        p_type: read_u32(&data[offset..offset+4], endian),
        p_flags: read_u32(&data[offset+4..offset+8], endian),
        p_offset: read_u64(&data[offset+8..offset+16], endian),
        p_vaddr: read_u64(&data[offset+16..offset+24], endian),
        p_paddr: read_u64(&data[offset+24..offset+32], endian),
        p_filesz: read_u64(&data[offset+32..offset+40], endian),
        p_memsz: read_u64(&data[offset+40..offset+48], endian),
        p_align: read_u64(&data[offset+48..offset+56], endian),
    })
}

fn parse_section_header_32(data: &[u8], offset: usize, endian: ElfData) -> Result<SectionHeader, String> {
    if offset + 40 > data.len() {
        return Err("Not enough data for section header".to_string());
    }

    Ok(SectionHeader {
        sh_name: read_u32(&data[offset..offset+4], endian),
        sh_type: read_u32(&data[offset+4..offset+8], endian),
        sh_flags: read_u32(&data[offset+8..offset+12], endian) as u64,
        sh_addr: read_u32(&data[offset+12..offset+16], endian) as u64,
        sh_offset: read_u32(&data[offset+16..offset+20], endian) as u64,
        sh_size: read_u32(&data[offset+20..offset+24], endian) as u64,
        sh_link: read_u32(&data[offset+24..offset+28], endian),
        sh_info: read_u32(&data[offset+28..offset+32], endian),
        sh_addralign: read_u32(&data[offset+32..offset+36], endian) as u64,
        sh_entsize: read_u32(&data[offset+36..offset+40], endian) as u64,
    })
}

fn parse_section_header_64(data: &[u8], offset: usize, endian: ElfData) -> Result<SectionHeader, String> {
    if offset + 64 > data.len() {
        return Err("Not enough data for section header".to_string());
    }

    Ok(SectionHeader {
        sh_name: read_u32(&data[offset..offset+4], endian),
        sh_type: read_u32(&data[offset+4..offset+8], endian),
        sh_flags: read_u64(&data[offset+8..offset+16], endian),
        sh_addr: read_u64(&data[offset+16..offset+24], endian),
        sh_offset: read_u64(&data[offset+24..offset+32], endian),
        sh_size: read_u64(&data[offset+32..offset+40], endian),
        sh_link: read_u32(&data[offset+40..offset+44], endian),
        sh_info: read_u32(&data[offset+44..offset+48], endian),
        sh_addralign: read_u64(&data[offset+48..offset+56], endian),
        sh_entsize: read_u64(&data[offset+56..offset+64], endian),
    })
}

fn read_u16(data: &[u8], endian: ElfData) -> u16 {
    match endian {
        ElfData::LittleEndian => u16::from_le_bytes([data[0], data[1]]),
        ElfData::BigEndian => u16::from_be_bytes([data[0], data[1]]),
    }
}

fn read_u32(data: &[u8], endian: ElfData) -> u32 {
    match endian {
        ElfData::LittleEndian => u32::from_le_bytes([data[0], data[1], data[2], data[3]]),
        ElfData::BigEndian => u32::from_be_bytes([data[0], data[1], data[2], data[3]]),
    }
}

fn read_u64(data: &[u8], endian: ElfData) -> u64 {
    match endian {
        ElfData::LittleEndian => u64::from_le_bytes([data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7]]),
        ElfData::BigEndian => u64::from_be_bytes([data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7]]),
    }
}
