            // Determine which field
            match elf_file.header.class {
                ElfClass::Bits32 => {
                    let offset = byte_index - shdr_start;
                    match offset {
                        0..=3 => classes.push("sh_name".to_string()),
                        4..=7 => classes.push("sh_type".to_string()),
                        8..=11 => classes.push("sh_flags".to_string()),
                        12..=15 => classes.push("sh_addr".to_string()),
