fn generate_hex_dump(elf_file: &ElfFile, data: &[u8]) -> String {
    let mut result = String::new();

    // Track the ranges for each structure
    let header_range = 0..match elf_file.header.class {
        ElfClass::Bits32 => 52,
        ElfClass::Bits64 => 64,
    };

    let mut byte_index = 0;

    while byte_index < data.len() {
        let mut line_html = String::new();

        for _ in 0..16 {
            if byte_index >= data.len() {
                break;
            }

            let byte = data[byte_index];

            // Determine what structure this byte belongs to
            let classes = get_byte_classes(elf_file, byte_index, data.len());

            let class_str = if classes.is_empty() {
                String::new()
            } else {
                format!(" class='{}'", classes.join(" "))
            };

            if byte_index > 0 && byte_index % 16 != 0 {
                line_html.push_str(" ");
            }

            if !class_str.is_empty() {
                line_html.push_str(&format!("<span{}><span class='byte'>{:02x}</span></span>", class_str, byte));
            } else {
                line_html.push_str(&format!("{:02x}", byte));
            }

            byte_index += 1;
        }

        result.push_str(&line_html);
        if byte_index < data.len() {
            result.push_str("\n");
        }
    }

    result
}

fn generate_ascii_dump(data: &[u8]) -> String {
    let mut result = String::new();

    for chunk in data.chunks(16) {
        for &byte in chunk {
            if byte >= 32 && byte <= 126 {
                result.push(byte as char);
            } else {
                result.push('.');
            }
        }
        result.push_str("\n");
    }

    result
}

fn get_byte_classes(elf_file: &ElfFile, byte_index: usize, file_size: usize) -> Vec<String> {
    let mut classes = Vec::new();

    // Check if this byte is in the ELF header
    let header_size = match elf_file.header.class {
        ElfClass::Bits32 => 52,
        ElfClass::Bits64 => 64,
    };

    if byte_index < header_size {
        classes.push("ehdr".to_string());

        // Check which field of the header
        if byte_index < 16 {
            classes.push("ident".to_string());
            match byte_index {
                0..=3 => classes.push("magic".to_string()),
                4 => classes.push("class".to_string()),
                5 => classes.push("data".to_string()),
                6 => classes.push("ver".to_string()),
                7 => classes.push("abi".to_string()),
                8 => classes.push("abi_ver".to_string()),
                9..=15 => classes.push("pad".to_string()),
                _ => {}
            }
        } else {
            match elf_file.header.class {
                ElfClass::Bits32 => {
                    match byte_index {
                        16..=17 => classes.push("e_type".to_string()),
                        18..=19 => classes.push("e_machine".to_string()),
                        20..=23 => classes.push("e_version".to_string()),
                        24..=27 => classes.push("e_entry".to_string()),
                        28..=31 => classes.push("e_phoff".to_string()),
                        32..=35 => classes.push("e_shoff".to_string()),
                        36..=39 => classes.push("e_flags".to_string()),
                        40..=41 => classes.push("e_ehsize".to_string()),
                        42..=43 => classes.push("e_phentsize".to_string()),
                        44..=45 => classes.push("e_phnum".to_string()),
                        46..=47 => classes.push("e_shentsize".to_string()),
                        48..=49 => classes.push("e_shnum".to_string()),
                        50..=51 => classes.push("e_shstrndx".to_string()),
                        _ => {}
                    }
                }
                ElfClass::Bits64 => {
                    match byte_index {
                        16..=17 => classes.push("e_type".to_string()),
                        18..=19 => classes.push("e_machine".to_string()),
                        20..=23 => classes.push("e_version".to_string()),
                        24..=31 => classes.push("e_entry".to_string()),
                        32..=39 => classes.push("e_phoff".to_string()),
                        40..=47 => classes.push("e_shoff".to_string()),
                        48..=51 => classes.push("e_flags".to_string()),
                        52..=53 => classes.push("e_ehsize".to_string()),
                        54..=55 => classes.push("e_phentsize".to_string()),
                        56..=57 => classes.push("e_phnum".to_string()),
                        58..=59 => classes.push("e_shentsize".to_string()),
                        60..=61 => classes.push("e_shnum".to_string()),
                        62..=63 => classes.push("e_shstrndx".to_string()),
                        _ => {}
                    }
                }
            }
        }
    }

    // Check program headers
    for (i, phdr) in elf_file.program_headers.iter().enumerate() {
        let phdr_start = elf_file.header.e_phoff as usize + (i * elf_file.header.e_phentsize as usize);
        let phdr_end = phdr_start + elf_file.header.e_phentsize as usize;

        if byte_index >= phdr_start && byte_index < phdr_end {
            classes.push(format!("bin_phdr{}", i));
            classes.push("phdr".to_string());

            // Determine which field
            match elf_file.header.class {
                ElfClass::Bits32 => {
                    let offset = byte_index - phdr_start;
                    match offset {
                        0..=3 => classes.push("p_type".to_string()),
                        4..=7 => classes.push("p_offset".to_string()),
                        8..=11 => classes.push("p_vaddr".to_string()),
                        12..=15 => classes.push("p_paddr".to_string()),
                        16..=19 => classes.push("p_filesz".to_string()),
                        20..=23 => classes.push("p_memsz".to_string()),
                        24..=27 => classes.push("p_flags".to_string()),
                        28..=31 => classes.push("p_align".to_string()),
                        _ => {}
                    }
                }
                ElfClass::Bits64 => {
                    let offset = byte_index - phdr_start;
                    match offset {
                        0..=3 => classes.push("p_type".to_string()),
                        4..=7 => classes.push("p_flags".to_string()),
                        8..=15 => classes.push("p_offset".to_string()),
                        16..=23 => classes.push("p_vaddr".to_string()),
                        24..=31 => classes.push("p_paddr".to_string()),
                        32..=39 => classes.push("p_filesz".to_string()),
                        40..=47 => classes.push("p_memsz".to_string()),
                        48..=55 => classes.push("p_align".to_string()),
                        _ => {}
                    }
                }
            }
        }
    }

    // Check section headers
    for (i, shdr) in elf_file.section_headers.iter().enumerate() {
        let shdr_start = elf_file.header.e_shoff as usize + (i * elf_file.header.e_shentsize as usize);
        let shdr_end = shdr_start + elf_file.header.e_shentsize as usize;

        if byte_index >= shdr_start && byte_index < shdr_end {
            classes.push(format!("bin_shdr{}", i));
            classes.push("shdr".to_string());

            // Determine which field
            match elf_file.header.class {
                ElfClass::Bits32 => {
                    let offset = byte_index - shdr_start;
                    match offset {
                        0..=3 => classes.push("sh_name".to_string()),
                        4..=7 => classes.push("sh_type".to_string()),
                        8..=11 => classes.push("sh_flags".to_string()),
                        12..=15 => classes.push("sh_addr".to_string()),
                        16..=19 => classes.push("sh_offset".to_string()),
                        20..=23 => classes.push("sh_size".to_string()),
                        24..=27 => classes.push("sh_link".to_string()),
                        28..=31 => classes.push("sh_info".to_string()),
                        32..=35 => classes.push("sh_addralign".to_string()),
                        36..=39 => classes.push("sh_entsize".to_string()),
                        _ => {}
                    }
                }
                ElfClass::Bits64 => {
                    let offset = byte_index - shdr_start;
                    match offset {
                        0..=3 => classes.push("sh_name".to_string()),
                        4..=7 => classes.push("sh_type".to_string()),
                        8..=15 => classes.push("sh_flags".to_string()),
                        16..=23 => classes.push("sh_addr".to_string()),
                        24..=31 => classes.push("sh_offset".to_string()),
                        32..=39 => classes.push("sh_size".to_string()),
                        40..=43 => classes.push("sh_link".to_string()),
                        44..=47 => classes.push("sh_info".to_string()),
                        48..=55 => classes.push("sh_addralign".to_string()),
                        56..=63 => classes.push("sh_entsize".to_string()),
                        _ => {}
                    }
                }
            }
        }
    }

    classes
}

fn format_size(bytes: u64) -> String {
    if bytes == 1 {
        "1 B".to_string()
    } else {
        format!("{} B", bytes)
    }
}

fn format_hex(value: u64) -> String {
    format!("0x{:x}", value)
}

